import{_ as a,o,c as d,a2 as t}from"./chunks/framework.Boholvbs.js";const p=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1791786611000}'),i={name:"guide/faq.md"};function r(c,e,l,h,n,s){return o(),d("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="创建密钥时找不到我买的那档" tabindex="-1">创建密钥时找不到我买的那档 <a class="header-anchor" href="#创建密钥时找不到我买的那档" aria-label="Permalink to &quot;创建密钥时找不到我买的那档&quot;">​</a></h2><p>订阅类分组只在订阅生效后出现。到「我的订阅」确认这一档存在且没过期；刚付款的话刷新一下页面。</p><h2 id="提示额度用完-请求被拒" tabindex="-1">提示额度用完 / 请求被拒 <a class="header-anchor" href="#提示额度用完-请求被拒" aria-label="Permalink to &quot;提示额度用完 / 请求被拒&quot;">​</a></h2><p>每档有每日、每周两道上限。到「我的订阅」看是哪一道用完了，等对应周期重置即可，或升级到更高一档。</p><h2 id="_401-密钥无效" tabindex="-1">401 / 密钥无效 <a class="header-anchor" href="#_401-密钥无效" aria-label="Permalink to &quot;401 / 密钥无效&quot;">​</a></h2><ul><li>密钥复制完整了吗？前后不要有空格</li><li>密钥是否已被删除或禁用（「API 密钥」页看状态）</li><li>Claude Code 用的是 <code>ANTHROPIC_AUTH_TOKEN</code>，不是 <code>ANTHROPIC_API_KEY</code></li></ul><h2 id="_404-或地址不对" tabindex="-1">404 或地址不对 <a class="header-anchor" href="#_404-或地址不对" aria-label="Permalink to &quot;404 或地址不对&quot;">​</a></h2><ul><li>Claude Code：<code>https://relay.panghuli.tech</code>，<strong>不带</strong> <code>/v1</code></li><li>Codex 和其他 OpenAI 兼容客户端：<code>https://relay.panghuli.tech/v1</code>，<strong>要带</strong> <code>/v1</code></li></ul><h2 id="用-cc-switch-code-switch-的本地代理时报-401「invalid-api-key」" tabindex="-1">用 CC Switch / Code Switch 的本地代理时报 401「Invalid API key」 <a class="header-anchor" href="#用-cc-switch-code-switch-的本地代理时报-401「invalid-api-key」" aria-label="Permalink to &quot;用 CC Switch / Code Switch 的本地代理时报 401「Invalid API key」&quot;">​</a></h2><p>把工具里本站服务商的<strong>鉴权方式改成 Bearer</strong>，不要选 <code>x-api-key</code>。</p><p>这类工具开启本地代理时，会让 Claude Code 带一个占位令牌发到代理；鉴权方式选 <code>x-api-key</code> 时，代理只追加 <code>x-api-key</code>，不替换原来的 <code>Authorization</code>。本站优先读 <code>Authorization</code>，读到的是占位令牌，于是拒绝。选 Bearer 后代理会用真实密钥覆盖它。（Code Switch 已实测；其他带本地代理的切换工具同样先检查这一项。）</p><h2 id="claude-的密钥能用在-codex-上吗" tabindex="-1">Claude 的密钥能用在 Codex 上吗 <a class="header-anchor" href="#claude-的密钥能用在-codex-上吗" aria-label="Permalink to &quot;Claude 的密钥能用在 Codex 上吗&quot;">​</a></h2><p>不能。一个密钥只对应创建时选的那个分组，Claude 和 Codex 各建一个。</p><h2 id="用量记录在哪看" tabindex="-1">用量记录在哪看 <a class="header-anchor" href="#用量记录在哪看" aria-label="Permalink to &quot;用量记录在哪看&quot;">​</a></h2><p>「使用记录」按请求列出模型、token 数和折算费用；「我的订阅」看额度剩余。</p>',16)])])}const _=a(i,[["render",r]]);export{p as __pageData,_ as default};
